{"command": "cd /home/user/rork-app && python3 - <<'PY'
import re
targets={'RENDER_API_KEY','IVX_RENDER_API_KEY','RENDER_SERVICE_ID','GITHUB_REPO_URL','Vercel'}
for line in open('expo/.env',encoding='utf-8',errors='replace'):
    line=line.strip()
    if not line or line.startswith('#') or '=' not in line: continue
    k,v=line.split('=',1); v=v.strip().strip('"').strip("'")
    if k not in targets: continue
    # Safe to show: if it's prose it is NOT a credential. Detect prose first.
    prose = bool(re.search(r'\s', v)) or not re.match(r'^[A-Za-z0-9_\-\.:/]+$', v)
    if prose:
        print(f'  {k:<22} PROSE/NOT-A-CREDENTIAL -> "{v[:70]}..."' if len(v)>70 else f'  {k:<22} PROSE/NOT-A-CREDENTIAL -> "{v}"')
    else:
        print(f'  {k:<22} opaque token-like, len={len(v)}, prefix="{v[:8]}"')
PY"}

